export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdEntries = Object.entries(thresholds);
  const thresholdResults = thresholdEntries.map(([metricId, min]) => {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric?.score ?? null;
    const passed = score !== null && score >= min;
    return {
      metric: metricId,
      min,
      score,
      passed
    };
  });

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdResults.length > 0) {
    report.passed = thresholdResults.every((t) => t.passed);
    report.thresholds = thresholdResults;
  }

  return report;
}

